/*
 * Guards the committed fidelity-allowlist.json against the failure that produced build 30490:
 * the baseline and the harness that generates it drifting apart.
 *
 * What happened: an experiment that set request.WorkflowsDirectory was used to generate the
 * allow-list, then the code was reverted to the EnsureIndexed approach and the generated file was
 * committed anyway. The two configurations disagree on six activity types, so the next CI run
 * reported three phantom regressions and four phantom improvements — and, worse, shipped an
 * allow-list marking Assign and Decision non-editable, which forces bodyEditable:false on
 * essentially every real workflow.
 *
 * Nothing about that was visible in the diff. The provenance block, and these tests, make it
 * visible: a baseline that cannot prove which harness produced it is not usable as a baseline.
 */

using System;
using System.IO;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Newtonsoft.Json;

namespace Warewolf.Execution.Lightweight.Integration.Tests.Coverage
{
    [TestClass]
    [TestCategory("RoundTripFidelity")]
    public class FidelityBaselineProvenanceTests
    {
        static string CommittedBaselinePath =>
            Path.Combine(AppContext.BaseDirectory, "Resources", "fidelity-allowlist.json");

        static BaselineDocument LoadCommittedBaselineOrInconclusive()
        {
            var path = CommittedBaselinePath;
            if (!File.Exists(path))
            {
                Assert.Inconclusive(
                    "No fidelity baseline shipped beside the test binaries at " + path +
                    ". It is copied there from Dev/Warewolf.Execution.Lightweight/Resources by the build.");
            }

            var document = JsonConvert.DeserializeObject<BaselineDocument>(File.ReadAllText(path));
            Assert.IsNotNull(document, "the committed baseline at " + path + " did not parse as JSON");
            return document!;
        }

        // ── The rule ──────────────────────────────────────────────────────────

        [TestMethod]
        public void DescribeProvenanceMismatch_BaselineWithNoHarnessBlock_ExplainsItCannotBeTrusted()
        {
            var message = FidelityRegressionGate.DescribeProvenanceMismatch(new BaselineDocument());

            Assert.IsNotNull(message);
            StringAssert.Contains(message!, "harness");
            StringAssert.Contains(message!, "fidelity-allowlist.json",
                "the message must say how to fix it, not just that something is wrong");
        }

        [TestMethod]
        public void DescribeProvenanceMismatch_BaselineFromAnEarlierHarness_ExplainsItIsNotComparable()
        {
            var stale = new BaselineDocument
            {
                Harness = new HarnessProvenance
                {
                    HarnessVersion = FidelityRegressionGate.CurrentHarnessVersion - 1,
                },
            };

            var message = FidelityRegressionGate.DescribeProvenanceMismatch(stale);

            Assert.IsNotNull(message);
            StringAssert.Contains(message!, (FidelityRegressionGate.CurrentHarnessVersion - 1).ToString());
            StringAssert.Contains(message!, FidelityRegressionGate.CurrentHarnessVersion.ToString());
        }

        [TestMethod]
        public void DescribeProvenanceMismatch_BaselineFromThisHarness_IsAccepted()
        {
            var current = new BaselineDocument
            {
                Harness = new HarnessProvenance
                {
                    HarnessVersion = FidelityRegressionGate.CurrentHarnessVersion,
                },
            };

            Assert.IsNull(FidelityRegressionGate.DescribeProvenanceMismatch(current));
        }

        // ── The committed file ────────────────────────────────────────────────

        [TestMethod]
        public void CommittedBaseline_WasGeneratedByThisHarnessVersion()
        {
            // Fails the moment someone bumps CurrentHarnessVersion without regenerating the
            // allow-list, or commits an allow-list generated by a different build. That is the
            // whole point: the drift must be loud at the commit that causes it.
            var baseline = LoadCommittedBaselineOrInconclusive();

            var mismatch = FidelityRegressionGate.DescribeProvenanceMismatch(baseline);
            Assert.IsNull(mismatch, mismatch);
        }

        [TestMethod]
        public void CommittedBaseline_RecordsTheCorpusItWasMeasuredAgainst()
        {
            // Without this, a row's status cannot be attributed to a corpus, and the gate cannot
            // tell "this activity regressed" from "this activity was measured against a sample the
            // current run cannot see".
            var baseline = LoadCommittedBaselineOrInconclusive();

            Assert.IsNotNull(baseline.Harness);
            Assert.IsTrue(baseline.Harness!.CorpusRoots.Count > 0,
                "the committed baseline records no corpus roots, so its rows cannot be attributed");
            Assert.IsTrue(baseline.Harness.MaxSamplesPerType > 0,
                "the committed baseline records no sample bound, so how hard it looked is unknown");
        }

        [TestMethod]
        public void CommittedBaseline_HasResults()
        {
            var baseline = LoadCommittedBaselineOrInconclusive();

            Assert.IsNotNull(baseline.Results);
            Assert.IsTrue(baseline.Results!.Count > 0, "an empty allow-list makes every workflow non-editable");
        }

        // ── Serialisation ─────────────────────────────────────────────────────

        [TestMethod]
        public void HarnessProvenance_SurvivesTheRoundTripThroughTheGeneratedFile()
        {
            // The gate reads what the sweep writes; a property-name mismatch between the two would
            // silently reproduce the "no provenance" state this whole mechanism exists to detect.
            var written = JsonConvert.SerializeObject(new
            {
                generatedAtUtc = DateTime.UtcNow,
                harness = new HarnessProvenance
                {
                    HarnessVersion = FidelityRegressionGate.CurrentHarnessVersion,
                    MaxSamplesPerType = 8,
                    CorpusRoots = new System.Collections.Generic.List<string> { "Resources - Release" },
                },
                results = Array.Empty<object>(),
            }, Formatting.Indented);

            var read = JsonConvert.DeserializeObject<BaselineDocument>(written);

            Assert.IsNotNull(read?.Harness);
            Assert.AreEqual(FidelityRegressionGate.CurrentHarnessVersion, read!.Harness!.HarnessVersion);
            Assert.AreEqual(8, read.Harness.MaxSamplesPerType);
            CollectionAssert.AreEqual(new[] { "Resources - Release" }, read.Harness.CorpusRoots);
            Assert.IsNull(FidelityRegressionGate.DescribeProvenanceMismatch(read));
        }
    }
}
